def solve(nums, k):
    def heapify_and_pop(arr, n, i, k):
        largest = i
        l = 2 * i + 1
        r = 2 * i + 2

        if l < n and arr[l] > arr[largest]:
            largest = l

        if r < n and arr[r] > arr[largest]:
            largest = r

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify_and_pop(arr, n, largest, k)

    n = len(nums)
    largest = 0
    for i in range(n):
        heapify_and_pop(nums, n, largest, k)
        if nums[largest] == nums[i]:
            largest = i

    return nums[largest]
