def solve(nums, k):
    """
    Finds the k-th smallest value in nums using quickselect.

    Args:
        nums: A list of integers with 1 <= len(nums) <= 2000,
              and every value lies between -10000 and 10000 inclusive;
              values may repeat.
        k: An integer with 1 <= k <= len(nums), counted from 1.

    Returns:
        The k-th smallest value in nums.
    """

    def partition(left, right, pivot_index):
        pivot = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] < pivot:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left, right, k):
        if left == right:
            return nums[left]

        pivot_index = (left + right) // 2
        pivot_index = partition(left, right, pivot_index)

        if k == pivot_index + 1:
            return nums[pivot_index]
        elif k < pivot_index + 1:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k)
