        if i in memo:
            return memo[i]

        if i == len(intervals):
            return 0

        # Option 1: Skip the current interval
        skip = take_or_skip(i + 1)

        # Option 2: Take the current interval
        take = 1 + take_or_skip(i + 1)

        # Determine if current interval overlaps with previous intervals
        overlap = False
        if i > 0:
            prev_end = intervals[i-1][1]
            curr_start = intervals[i][0]
            if curr_start < prev_end:
                overlap = True

        memo[i] = min(skip, take)
        return memo[i]

    return take_or_skip(0)
