        cache = {}
        def inner(i):
            if i in cache:
                return cache[i]
            result = func(i)
            cache[i] = result
            return result
        return inner

    @memoize
    def helper(i):
        if i == -1:
            return 0

        # Option 1: Skip the current interval
        skip = 1 + helper(i - 1)

        # Option 2: Take the current interval
        take = 0
        prev_end = float('-inf')
        for j in range(i, -1, -1):
            if intervals[j][1] > prev_end:
                take = min(take, helper(j))
                prev_end = intervals[j][1]

        return min(skip, take)

    return helper(len(intervals) - 1)
