def solve(n, prerequisites):
    graph = [[] for _ in range(n)]
    in_degree = [0] * n
    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    post_order = []
    visited = [False] * n

    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        post_order.append(node)

    for i in range(n):
        if not visited[i]:
            dfs(i)

    if len(post_order) != n:
        return []

    return post_order[::-1]
```

