class IntervalTreeNode:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.max_end = end
        self.left = None
        self.right = None

class IntervalTree:
    def __init__(self):
        self.root = None

    def insert(self, start, end):
        self.root = self._insert(self.root, start, end)

    def _insert(self, node, start, end):
        if node is None:
            return IntervalTreeNode(start, end)

        if start < node.start:
            node.left = self._insert(node.left, start, end)
        else:
            node.right = self._insert(node.right, start, end)

        node.max_end = max(node.max_end, end)
        return node

    def query(self, start, end):
        return self._query(self.root, start, end)

    def _query(self, node, start, end):
        if node is None:
            return None

        if node.start <= start and node.end >= end:
            return node

        if node.end < start:
            return self._query(node.right, start, end)

        if node.start > end:
            return self._query(node.left, start, end)

        return self._merge(node, start, end)

    def _merge(self, node, start, end):
        if node is None:
            return None

        left_result = self._query(node.left, start, end)
        right_result = self._query(node.right, start, end)

        if left_result is None:
            return right_result
        if right_result is None:
            return left_result

        if left_result.end < right_result.start:
            merged_start = left_result.start
            merged_end = max(left_result.end, right_result.end)
            return IntervalTreeNode(merged_start, merged_end)
        else:
            merged_start = min(left_result.start, right_result.start)
            merged_end = max(left_result.end, right_result.end)
            return IntervalTreeNode(merged_start, merged_end)

def solve(intervals):
    if not intervals:
        return []

    intervals.sort()
    merged = []
    tree = IntervalTree()

    for interval in intervals:
        start, end = interval
        result = tree.query(start, end)
        if result is None:
            merged.append(interval)
            tree.insert(start, end)
        else:
            result_start, result_end = result.start, result.end
            if start <= result_end:
                new_start = min(start, result_start)
                new_end = max(end, result_end)
                tree.insert(new_start, new_end)
                merged[-1] = [new_start,new_end]
            else:
                merged.append(interval)
                tree.insert(start, end)

    result_merged = []
    for interval in merged:
        start, end = interval
        result_merged.append([start,end])

    result_merged.sort()

    final_merged = []
    if not result_merged:
        return []

    final_merged.append(result_merged[0])
    for i in range(1, len(result_merged)):
        last_start, last_end = final_merged[-1]
        curr_start, curr_end = result_merged[i]

        if curr_start <= last_end:
            final_merged[-1][1] = max(last_end, curr_end)
        else:
            final_merged.append([curr_start, curr_end])

    return final_merged
