        return []

    parent = list(range(len(intervals)))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if (intervals[i][1] >= intervals[j][0] and intervals[i][0] <= intervals[j][1]) or \
               (intervals[j][1] >= intervals[i][0] and intervals[j][0] <= intervals[i][1]):
                union(i, j)

    merged = []
    for i in range(len(intervals)):
        root = find(i)
        if root not in [find(j) for j in range(len(intervals)) if find(j) == root]:
            merged.append(intervals[i])

    merged.sort()
    return merged
