    def binary_search(nums, target, first, last):
        while first <= last:
            mid = (first + last) // 2
            if nums[mid] == target:
                # Found a match, now find the first and last occurrences
                l = mid
                r = mid
                while l > 0 and nums[l - 1] == target:
                    l -= 1
                while r < len(nums) - 1 and nums[r + 1] == target:
                    r += 1
                return [l, r]
            elif nums[mid] < target:
                first = mid + 1
            else:
                last = mid - 1
        return [-1, -1]

    return binary_search(nums, target, 0, len(nums) - 1)
