def solve(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    nums = list(counts.keys())

    def partition(arr, low, high):
        pivot = arr[high]
        i = low
        for j in range(low, high):
            if arr[j] <= pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[high] = arr[high], arr[i]
        return i

    def quickselect(arr, low, high, k):
        if low == high:
            return arr[low]

        pivot_index = partition(arr, low, high)

        if k == pivot_index + 1:
            return arr[pivot_index]
        elif k < pivot_index + 1:
            return quickselect(arr, low, pivot_index - 1, k)
        else:
            return quickselect(arr, pivot_index + 1, high, k)

    frequencies = [counts[num] for num in nums]

    sorted_frequencies = sorted(frequencies, reverse=True)

    kth_frequency = quickselect(frequencies, 0, len(frequencies) - 1, k)

    result = []
    for num in nums:
        if counts[num] == kth_frequency:
            result.append(num)

    return result
```

