def solve(nums):
    if not nums:
        return 0

    compressed_nums = sorted(list(set(nums)))
    value_map = {val: i + 1 for i, val in enumerate(compressed_nums)}

    bit = [0] * (len(compressed_nums) + 1)

    def update(i, val):
        while i < len(bit):
            bit[i] = max(bit[i], val)
            i += i & -i

    def query(i):
        res = 0
        while i > 0:
            res = max(res, bit[i])
            i -= i & -i
        return res

    for num in nums:
        idx = value_map[num]
        length = query(idx - 1) + 1
        update(idx, length)

    return query(len(compressed_nums))
