def solve(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    recursion_stack = [False] * n

    def dfs(node, parent):
        visited[node] = True
        recursion_stack[node] = True

        for neighbor in adj[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent and recursion_stack[neighbor]:
                return True

        recursion_stack[node] = False
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, -1):
                return True

    return False
