def solve(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    parent = [-1] * n

    def bfs(start_node):
        q = deque([start_node])
        visited[start_node] = True

        while q:
            u = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    return True
        return False

    for i in range(n):
        if not visited[i]:
            if bfs(i):
                return True

    return False
