def solve(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    parent = [-1] * n

    for start_node in range(n):
        if not visited[start_node]:
            queue = deque([start_node])
            visited[start_node] = True

            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
                        parent[v] = u
                    elif parent[u] != v:
                        return True

    return False
```

