import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist_forward = [float('inf')] * n
    dist_backward = [float('inf')] * n
    dist_forward[s] = 0
    dist_backward[t] = 0

    pq_forward = [(0, s)]
    pq_backward = [(0, t)]

    while pq_forward:
        d, u = heapq.heappop(pq_forward)

        if d > dist_forward[u]:
            continue

        for v, w in graph[u]:
            if dist_forward[v] > dist_forward[u] + w:
                dist_forward[v] = dist_forward[u] + w
                heapq.heappush(pq_forward, (dist_forward[v], v))

    while pq_backward:
        d, u = heapq.heappop(pq_backward)

        if d > dist_backward[u]:
            continue

        for u_rev, w in graph[u]:
            if dist_backward[u_rev] > dist_backward[u] + w:
                dist_backward[u_rev] = dist_backward[u] + w
                heapq.heappush(pq_backward, (dist_backward[u_rev], u_rev))

    if dist_forward[t] == float('inf') and dist_backward[s] == float('inf'):
        return -1

    if dist_forward[t] == float('inf'):
        return -1

    return dist_forward[t] + dist_backward[s]
