    for u in range(n):
        for edge_u, edge_v, weight in edges:
            if edge_u == u and dist[edge_v] > dist[u] + weight:
                dist[edge_v] = dist[u] + weight
            elif edge_v == u and dist[edge_v] > dist[u] + weight:
                dist[edge_v] = dist[u] + weight
    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
