def solve(nums, k):
    def median(arr):
        arr.sort()
        n = len(arr)
        if n % 2 == 0:
            return (arr[n // 2 - 1] + arr[n // 2]) // 2
        else:
            return arr[n // 2]

    def quickselect(arr, left, right, k):
        if left == right:
            return arr[left]

        pivot_index = (left + right) // 2
        pivot_value = arr[pivot_index]

        i = left
        j = right
        while i <= j:
            while arr[i] < pivot_value:
                i += 1
            while arr[j] > pivot_value:
                j -= 1
            if i <= j:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1

        quickselect(arr, left, j, k)
        quickselect(arr, i, right, k)

    n = len(nums)
    if k == 1:
        return min(nums)
    elif k == n:
        return max(nums)

    medians = []
    for i in range(0, n, int(n**0.5)):
        subarray = nums[i:i + int(n**0.5)]
        medians.append(median(subarray))

    if medians[0] == min(nums):
        return min(nums)
    elif medians[-1] == max(nums):
        return max(nums)

    for i in range(n):
        if nums[i] == medians[0]:
            nums[i] = float('inf')
        if nums[i] == medians[-1]:
            nums[i] = float('-inf')

    return quickselect(nums, 0, n - 1, k)
