from heapq import heappush, heappop

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def get_neighbors(row, col):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col):
                neighbors.append((new_row, new_col))
        return neighbors

    open_set = [(0, start)]  # (f_score, (row, col))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while open_set:
        current_f_score, current = heappop(open_set)
        if current == goal:
            return reconstruct_path(came_from, current)

        for neighbor_row, neighbor_col in get_neighbors(current[0], current[1]):
            tentative_g_score = g_score[current] + 1
            if (neighbor_row, neighbor_col) not in g_score or tentative_g_score < g_score[(neighbor_row, neighbor_col)]:
                came_from[(neighbor_row, neighbor_col)] = current
                g_score[(neighbor_row, neighbor_col)] = tentative_g_score
                f_score[(neighbor_row, neighbor_col)] = tentative_g_score + heuristic((neighbor_row, neighbor_col), goal)
                heappush(open_set, (f_score[(neighbor_row, neighbor_col)], (neighbor_row, neighbor_col)))

    return []

def heuristic(node, goal):
    return abs(node[0] - goal[0]) + abs(node[1] - goal[1])

def reconstruct_path(came_from, current):
    path = [current]
    while current in came_from:
        current = came_from[current]
        path.append(current)
    return path[::-1]
