def solve(n):
    """
    Calculates the n-th Fibonacci number using fast doubling.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1

    a, b = 0, 1
    for i in range(n.bit_length() - 1, -1, -1):
        c = a * (2 * b - a)
        d = a * a + b * b
        if (n >> i) & 1:
            a, b = d, c + d
        else:
            a, b = c, d

    return a
```

