class IntervalTreeNode:
    def __init__(self, interval):
        self.interval = interval
        self.max_end = interval[1]
        self.left = None
        self.right = None


def insert_interval(root, interval):
    if root is None:
        return IntervalTreeNode(interval)

    if interval[0] < root.interval[0]:
        root.left = insert_interval(root.left, interval)
    elif interval[1] > root.max_end:
        root.right = insert_interval(root.right, interval)
    else:
        root.interval[0] = min(root.interval[0], interval[0])
        root.max_end = max(root.max_end, interval[1])

    return root


def merge_intervals(root):
    if root is None:
        return []

    merged_intervals = []
    stack = [root]

    while stack:
        node = stack.pop()
        while node:
            if not merged_intervals or node.interval[0] > merged_intervals[-1][1]:
                merged_intervals.append(node.interval)
            else:
                merged_intervals[-1][1] = max(merged_intervals[-1][1], node.interval[1])

            if node.left:
                stack.append(node.left)
            node = node.right

    return merged_intervals


def solve(intervals):
    if not intervals:
        return []

    intervals.sort()
    root = None
    for interval in intervals:
        root = insert_interval(root, interval)

    merged_intervals = merge_intervals(root)
    return merged_intervals
```

