import random
from collections import Counter

def solve(nums, k):
    counts = Counter(nums)
    values = list(counts.values())
    n = len(values)

    def partition(l, r):
        pivot = random.choice(values[l:r+1])
        i = l
        for j in range(l, r):
            if values[j] < pivot:
                values[i], values[j] = values[j], values[i]
                i += 1
        values[i], values[r] = values[r], values[i]
        return i

    left, right = 0, n - 1
    while left < right:
        pivot_index = partition(left, right)
        if pivot_index == k - 1:
            break
        elif pivot_index < k - 1:
            left = pivot_index + 1
        else:
            right = pivot_index - 1

    result = []
    for i in range(n):
        if i < k:
            result.append(values[i])
    return result
