import random
from collections import Counter

def quickselect(arr, k):
    if not arr:
        return None

    def partition(l, r):
        pivot = random.choice(arr[l:r+1])
        i = l
        for j in range(l, r+1):
            if arr[j] < pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[r] = arr[r], arr[i]
        return i

    l, r = 0, len(arr) - 1
    while l <= r:
        pivot_index = partition(l, r)
        if pivot_index == k - 1:
            return arr[pivot_index]
        elif pivot_index < k - 1:
            l = pivot_index + 1
        else:
            r = pivot_index - 1
    return None

def solve(nums, k):
    counts = Counter(nums)
    frequencies = list(counts.values())

    if not frequencies:
        return []

    quickselect(frequencies, k)

    result = []
    for num in counts:
        if counts[num] == frequencies[quickselect(frequencies, k) - 1]:
            result.append(num)

    return result
```

